function StatusIcon({ status }: { status: string }) {
  if (status === "Cancelled")
    return <XCircle size={14} color="var(--theme-danger)" />;
  return <CheckCircle size={14} color="var(--theme-success)" />;
}

function StatusLabel({ status }: { status: string }) {
